BEGIN;
CREATE SCHEMA delivery_test;CREATE FUNCTION delivery_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;CREATE FUNCTION delivery_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;GRANT USAGE ON SCHEMA delivery_test TO anon,authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA delivery_test TO anon,authenticated;
INSERT INTO auth.users(id,email) VALUES('2b000000-0000-4000-8000-000000000001','delivery@example.invalid');INSERT INTO public.companies(id,nome,created_by) VALUES('1b000000-0000-4000-8000-000000000001','Delivery fixture','2b000000-0000-4000-8000-000000000001'),('1b000000-0000-4000-8000-000000000002','Other fixture','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1b000000-0000-4000-8000-000000000001','2b000000-0000-4000-8000-000000000001','administrador','admin_empresa','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual,ano_fabricacao,ano_modelo,chassi,renavam) VALUES('3b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','EXL0001','caminhao','Volvo FH',1000,2022,2023,'9BWZZZ377VT004251','12345678901');
SELECT set_config('request.jwt.claim.sub','2b000000-0000-4000-8000-000000000001',true);SET LOCAL ROLE authenticated;
INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,onboarding_profile) VALUES('4b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','Delivery workshop','11987654321','{"prazo_entrega_dias":3}');
SELECT set_config('delivery_test.id',public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','create','{"vehicle_id":"3b000000-0000-4000-8000-000000000001","partner_id":"4b000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"media","descricao_problema":"Freio","km_abertura":1000}')->>'id',true);
SELECT delivery_test.assert((SELECT prazo_entrega_dias=3 AND previsao_entrega IS NULL FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'partner interval copied without starting countdown');
SELECT delivery_test.assert((SELECT count(*)=1 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND kind='abertura' AND status='pending'),'opening queued once');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','document',jsonb_build_object('id',current_setting('delivery_test.id')))->'vehicle'->>'chassi'='9BWZZZ377VT004251','document includes persisted chassis');
SELECT delivery_test.denied($q$SELECT snapshot FROM public.maintenance_order_dispatches$q$);
SELECT delivery_test.denied($q$SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000002','document',jsonb_build_object('id',current_setting('delivery_test.id')))$q$);
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','item_save',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'tipo','servico','descricao','Reparo freio','quantidade',1,'valor_unitario',100));
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','summary',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'prazo_entrega_dias',NULL));
SELECT delivery_test.denied($q$SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','budget',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'decisao','aprovado','observacao','Sem prazo'))$q$);
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','budget',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'decisao','aprovado','observacao','Aprovado','prazo_entrega_dias',5));
SELECT delivery_test.assert((SELECT prazo_entrega_dias=5 AND prazo_base_aprovacao_em=aprovado_em AND abs(extract(epoch from (previsao_entrega-aprovado_em))-5*86400)<1 FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'five calendar days start at actual approval');
SELECT set_config('delivery_test.claim',public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura'))::text,true);
SELECT delivery_test.assert(current_setting('delivery_test.claim')::jsonb->>'phone'='5511987654321','recipient comes from partner');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura'))->>'status'='sending','concurrent claim cannot duplicate');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','finish',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','token',current_setting('delivery_test.claim')::jsonb->>'token','status','accepted','message_id','fixture-message'));
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura'))->>'status'='accepted','accepted file cannot be resent accidentally');
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','item_save',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'tipo','servico','descricao','Outro reparo','quantidade',1,'valor_unitario',10));
SELECT delivery_test.assert((SELECT prazo_base_aprovacao_em IS NULL AND previsao_entrega IS NULL FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'invalidated budget removes old estimate');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','aprovacao'))->>'status'='obsolete','obsolete budget is never dispatched');
SELECT delivery_test.assert((SELECT count(*)>0 FROM public.maintenance_order_timeline WHERE order_id=current_setting('delivery_test.id')::uuid AND descricao='Excel e mensagem aceitos pela Evolution API'),'file send audited in timeline');
RESET ROLE;SELECT set_config('request.jwt.claim.sub','',true);SET LOCAL ROLE anon;SELECT delivery_test.denied($q$SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','document',jsonb_build_object('id',current_setting('delivery_test.id')))$q$);RESET ROLE;ROLLBACK;
